/// <summary>
/// PaffH 10.11.25
/// last modified: PaffH 25.11.25
/// </summary>
/// <param name = "_sectionType">NDXBVEmailRequestSectionType</param>
protected void new(NDXBVEmailRequestSectionType _sectionType)
{
    super(_sectionType);

    this.addFields2Section(fieldNum(NDXBVEMailRequestHeader, ProjectIdentifier), 
        fieldNum(NDXBVEMailRequestHeaderAIDecisionBasis, ProjectIdentifierAIDB),
        fieldNum(NDXBVEMailRequestHeaderAIInfo, ProjectIdentifierAII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestHeader, ProjectAddressStreet), 
        fieldNum(NDXBVEMailRequestHeaderAIDecisionBasis, ProjectAddressStreetAIDB),
        fieldNum(NDXBVEMailRequestHeaderAIInfo, ProjectAddressStreetAII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestHeader, ProjectAddressZipCode), 
        fieldNum(NDXBVEMailRequestHeaderAIDecisionBasis, ProjectAddressZipCodeAIDB),
        fieldNum(NDXBVEMailRequestHeaderAIInfo, ProjectAddressZipCodeAII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestHeader, ProjectAddressCity), 
        fieldNum(NDXBVEMailRequestHeaderAIDecisionBasis, ProjectAddressCityAIDB),
        fieldNum(NDXBVEMailRequestHeaderAIInfo, ProjectAddressCityAII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestHeader, ProjectAddressCountryRegionISOCode), 
        fieldNum(NDXBVEMailRequestHeaderAIDecisionBasis, ProjectAddressCountryRegionISOCodeAIDB),
        fieldNum(NDXBVEMailRequestHeaderAIInfo, ProjectAddressCountryRegionISOCodeAII));
}

/// <summary>
/// PaffH 10.11.25
/// </summary>
/// <returns>NDXBVEmailRequestAIDBSectionProjectContract</returns>
public static NDXBVEmailRequestAIDBSectionProjectContract construct()
{
    NDXBVEmailRequestAIDBSectionProjectContract section = new NDXBVEmailRequestAIDBSectionProjectContract(NDXBVEmailRequestSectionType::ContactPerson);
    return section;
}
